import{K as l,a as r,c as i,b as a,k as n,q as c,ac as h}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"Outlook 日历、会议邀请与时间管理","description":"创建个人日程与会议邀请，使用忙闲状态、时区、重复事件、会议室和更新取消流程，避免重复会议和错时参会。","frontmatter":{"title":"Outlook 日历、会议邀请与时间管理","description":"创建个人日程与会议邀请，使用忙闲状态、时区、重复事件、会议室和更新取消流程，避免重复会议和错时参会。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Outlook 邮件与日程","summary":"创建个人日程与会议邀请，使用忙闲状态、时区、重复事件、会议室和更新取消流程，避免重复会议和错时参会。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Outlook 搜索、文件夹、分类与规则","link":"/tools/office/outlook/organize"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Outlook 搜索、文件夹、分类与规则","link":"/tools/office/outlook/organize"},"next":false},"headers":[],"relativePath":"tools/office/outlook/calendar.md","filePath":"tools/office/outlook/calendar.md"}'),s={name:"tools/office/outlook/calendar.md"},k=Object.assign(s,{setup(u){const o={path:"/tools/office/outlook/calendar",app:"Outlook",title:"安排一场时间与目的都清楚的会议",steps:[{tab:"开始",command:"新建会议",setting:"主题：月报口径确认；时长：30 分钟",anchor:"walkthrough-1"},{tab:"会议",command:"计划助理",setting:"检查参与者忙闲；核对会议室与时区",anchor:"walkthrough-2"},{tab:"会议",command:"发送更新",setting:"修改时间后通知参与者；取消应发送取消通知",anchor:"walkthrough-3"}]};return(d,e)=>{const t=l("OfficeGuide");return r(),i("div",null,[e[0]||(e[0]=a("h1",{id:"outlook-日历、会议邀请与时间管理",tabindex:"-1"},[n("Outlook 日历、会议邀请与时间管理 "),a("a",{class:"header-anchor",href:"#outlook-日历、会议邀请与时间管理","aria-label":'Permalink to "Outlook 日历、会议邀请与时间管理"'},"​")],-1)),e[1]||(e[1]=a("p",null,"个人日程用于安排自己的时间，会议邀请还涉及参会者、资源和通知。修改一项已发送会议时，应更新原会议，让参与者能追踪变化，而不是再建一个看起来相同的新事件。",-1)),c(t,{guide:o}),e[2]||(e[2]=h('<h2 id="create" tabindex="-1">创建日程与会议 <a class="header-anchor" href="#create" aria-label="Permalink to &quot;创建日程与会议 {#create}&quot;">​</a></h2><p>打开日历，选择日期和时间，新建事件或约会。填写明确主题、开始结束时间、地点和必要说明。只安排自己的阅读时间时可以不加参会者；添加参会者并发送后才涉及会议邀请流程。</p><p>会议说明至少包含目的、议程、会前材料和需要作出的决定。会议地点使用实际房间或有效在线会议链接，不要复制一条不属于本次会议的过期链接。Teams 等在线会议入口是否可用取决于账号和组织设置。</p><h2 id="availability" tabindex="-1">忙闲状态与会议室 <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;忙闲状态与会议室 {#availability}&quot;">​</a></h2><p>安排助手可帮助查看可见的忙闲信息，但他人的日历共享权限决定你能看到多少细节。显示为空闲也不保证对方一定方便，重要会议仍需按团队约定确认。</p><p>会议室一般是资源邮箱或组织配置的资源，通过房间选择器或添加资源邀请。写在地点文字里不一定等于成功预订；查看资源的接受或拒绝响应。容量、开放时间和审批规则由组织决定。</p><h2 id="timezone" tabindex="-1">时区与重复事件 <a class="header-anchor" href="#timezone" aria-label="Permalink to &quot;时区与重复事件 {#timezone}&quot;">​</a></h2><p>跨地区会议应确认日历时区和参与者所在地。填写时区信息时使用明确区域和日期，尤其注意夏令时变化；“下午三点”不足以让不同地区的人确定时间。全天事件也不能随意当作某个固定小时范围使用。</p><p>重复会议设置频率、每次时长和结束日期，例如每周二 10:00–10:30，持续四周。修改时确认是仅本次、后续事件还是整个系列，界面选项随版本不同。长期会议应定期复查是否仍有必要，不无限重复占位。</p><h2 id="update" tabindex="-1">更新、取消与响应 <a class="header-anchor" href="#update" aria-label="Permalink to &quot;更新、取消与响应 {#update}&quot;">​</a></h2><p>组织者修改时间、地点或关键内容后，使用更新会议功能向参与者发送变更。取消会议应从原事件执行取消并通知参会者，而不是只删除自己的日历显示。参会者删除本地副本与组织者取消整场会议含义不同。</p><p>接受、暂定或拒绝邀请时，检查是否发送了响应以及是否需要说明原因。提议新时间是否支持，取决于账号和版本；不支持时可通过正常沟通协调，但仍应由组织者最终更新原邀请。</p><h2 id="followup" tabindex="-1">提醒与会后行动 <a class="header-anchor" href="#followup" aria-label="Permalink to &quot;提醒与会后行动 {#followup}&quot;">​</a></h2><p>提醒提前量根据准备工作设置，重要演示应留出设备测试时间。会后把决策和行动记录到<a href="/tools/office/onenote/notes">OneNote 会议笔记</a>，为行动项指定负责人和截止日期，而不是把所有内容继续塞进会议信息框。</p><p>私人标记可能限制部分查看者看到详情，但不等同于完整的安全隔离；委派、管理员和组织政策仍可能影响可见性。不要把机密材料直接写入对广泛人员共享的事件说明。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>先创建仅自己可见的练习事件，时长 30 分钟，设置提醒。再复制为一项四周重复事件，修改其中一次并核对其他日期未变化。测试完删除练习事件；若要验证邀请与更新，使用自己的测试账号，避免给他人发送无意义通知。</p><p>参考：<a href="https://support.microsoft.com/en-us/outlook/calendar/introduction-to-the-outlook-calendar" target="_blank" rel="noopener noreferrer">Outlook 日历介绍</a>。</p><h2 id="walkthrough" tabindex="-1">图示跟做：安排一场时间与目的都清楚的会议 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：安排一场时间与目的都清楚的会议 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先创建可审阅的会议草稿 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先创建可审阅的会议草稿 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：开始 → 新建会议。</strong></p><p>在经典 Outlook 日历中新建会议；新版可新建事件后添加参与者。输入主题、开始结束时间和地点，在正文写会议目标、两项议题、需要提前阅读的材料。先保存为草稿或暂不发送，核对日期是否选错周。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：确认时间真的可参加 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：确认时间真的可参加 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：会议 → 计划助理。</strong></p><p>打开计划助理查看可用的忙闲信息，注意有些外部联系人不会显示完整状态。跨地区会议明确时区，会议室是否接受预订要看实际响应，不能仅因为写进地点栏就认为已预留。重复会议要设置结束日期，避免无限重复。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：理解邀请与本地备注的区别 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：理解邀请与本地备注的区别 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：会议 → 发送更新。</strong></p><p>正式确认后再发送邀请。后续改时间要更新原会议并发送更新，不要另建一个看似相同的会议让日历出现两个版本。取消时由组织者按应用流程发送取消通知；只从自己视图移除不等于其他人的日历已同步取消。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>本练习只需准备草稿并检查字段，实际邀请与更新由会议组织者确认发送。验收时看响应状态及会议室反馈，邮件发送成功不等于所有人已接受。</p>',31))])}}});export{f as __pageData,k as default};
